from inventory import discount
for price,rate in [(-1,.2),(10,-.1),(10,1.01)]:
    try: discount(price,rate)
    except ValueError: pass
    else: raise AssertionError((price,rate))
assert discount(10,0)==10 and discount(10,1)==0
assert abs(discount(12.5,.2)-10)<1e-9

from notes import slug_title
assert slug_title("  Hello   世界\tNotes ")=="Hello-世界-Notes"
assert slug_title("A_B")=="A_B"
for value in [""," \t\n"]:
    try: slug_title(value)
    except ValueError: pass
    else: raise AssertionError("空标题必须失败")

from stats import percentile
values=[30,0,10,20]
assert percentile(values,25)==7.5
assert percentile(values,50)==15 and values==[30,0,10,20]
assert percentile([7],0)==7 and percentile([7],100)==7
for value,p in [([],50),([1],-1),([1],101)]:
    try: percentile(value,p)
    except ValueError: pass
    else: raise AssertionError((value,p))
